class Solution {
  public int waysToDistribute(int n, int k) {
    final long MOD = 1_000_000_007L;
    // Stirling numbers of the second kind: candy i opens a new bag or joins one of j bags
    long[] dp = new long[k + 1];
    dp[0] = 1;
    for (int i = 1; i <= n; i++)
      for (int j = Math.min(i, k); j >= 1; j--) dp[j] = (dp[j - 1] + j * dp[j]) % MOD;
    return (int) dp[k];
  }
}
